/* 1. Global box-sizing — har bir loyiha shu bilan boshlanadi */
*, *::before, *::after {
  box-sizing: border-box;
}

/* 4. Element markazlash — grid orqali eng qisqa yo'l */
.centered {
  display: grid;
  place-items: center;
  min-height: 100vh;
}

/* 7. Media query'siz responsive grid */
.catalog {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: clamp(1rem, 2vw, 2rem);
}

/* 8. Container query — komponent ota konteyneriga moslashadi */
.card-list {
  container-type: inline-size;
}
@container (min-width: 480px) {
  .card {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 1rem;
  }
}

/* 10. Cascade layers — specificity urushini yakunlaydi */
@layer reset, base, components, utilities;

@layer utilities {
  /* utilities eng oxirgi qatlam — hatto past specificity ham g'olib */
  .mt-4 { margin-top: 1rem; }
}

/* 11. :where() — specificity 0, reset uchun ideal */
:where(button, [role="button"]) {
  cursor: pointer;
  font: inherit;
}

/* 16 + 17. CLS'ni oldini olish + contain */
.feed-item {
  contain: content;                     /* layout + paint izolyatsiyasi */
  content-visibility: auto;             /* ekrandan tashqarida — render yo'q */
  contain-intrinsic-size: 0 320px;      /* joy zaxirasi CLS'ga qarshi */
}

.hero-image {
  width: 100%;
  aspect-ratio: 16 / 9;                  /* rasm yuklangunga qadar joy tayyor */
  object-fit: cover;
  background: #eef2f7;
}

/* 19. Pseudo-class + pseudo-element birgalikda */
.link:hover::after {
  content: " ↗";
  color: currentColor;
  opacity: 0.7;
}

/* 20. Critical CSS — <head> ichida inline, faqat above-the-fold uchun */
:root {
  --font-body: 'Inter', system-ui, sans-serif;
  --color-text: #0b1220;
  --color-bg: #ffffff;
}

html { color-scheme: light dark; }
body {
  margin: 0;
  font-family: var(--font-body);
  color: var(--color-text);
  background: var(--color-bg);
  -webkit-font-smoothing: antialiased;
}

/* Font — CLS'ning ikkinchi fronti */
@font-face {
  font-family: 'Inter';
  src: url('/fonts/inter.woff2') format('woff2');
  font-display: swap;
  size-adjust: 100.5%;
}

/* 1. Глобальный box-sizing — с этого начинается любой проект */
*, *::before, *::after {
  box-sizing: border-box;
}

/* 4. Центрирование элемента — самый короткий путь через grid */
.centered {
  display: grid;
  place-items: center;
  min-height: 100vh;
}

/* 7. Адаптивный grid без media query */
.catalog {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: clamp(1rem, 2vw, 2rem);
}

/* 8. Container query — компонент подстраивается под родителя */
.card-list {
  container-type: inline-size;
}
@container (min-width: 480px) {
  .card {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 1rem;
  }
}

/* 10. Cascade layers — заканчивают войну специфичности */
@layer reset, base, components, utilities;

@layer utilities {
  /* utilities — последний слой, побеждает даже при низкой specificity */
  .mt-4 { margin-top: 1rem; }
}

/* 11. :where() — specificity 0, идеально для reset */
:where(button, [role="button"]) {
  cursor: pointer;
  font: inherit;
}

/* 16 + 17. Профилактика CLS + contain */
.feed-item {
  contain: content;                     /* изоляция layout + paint */
  content-visibility: auto;             /* вне экрана — не рендерится */
  contain-intrinsic-size: 0 320px;      /* резерв места против CLS */
}

.hero-image {
  width: 100%;
  aspect-ratio: 16 / 9;                  /* место готово до загрузки картинки */
  object-fit: cover;
  background: #eef2f7;
}

/* 19. Псевдокласс + псевдоэлемент вместе */
.link:hover::after {
  content: " ↗";
  color: currentColor;
  opacity: 0.7;
}

/* 20. Critical CSS — inline в <head>, только above-the-fold */
:root {
  --font-body: 'Inter', system-ui, sans-serif;
  --color-text: #0b1220;
  --color-bg: #ffffff;
}

html { color-scheme: light dark; }
body {
  margin: 0;
  font-family: var(--font-body);
  color: var(--color-text);
  background: var(--color-bg);
  -webkit-font-smoothing: antialiased;
}

/* Шрифт — второй фронт борьбы с CLS */
@font-face {
  font-family: 'Inter';
  src: url('/fonts/inter.woff2') format('woff2');
  font-display: swap;
  size-adjust: 100.5%;
}
